@namespace sv_a9dee7a0746c44b0bdb71bd304255b32.Components.Pages.Apply

<nav class="mb-4">
    <ol class="list-group list-group-horizontal text-center">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;

            <li class="list-group-item flex-fill @(isCurrent ? "list-group-item-primary fw-bold" : isCompleted ? "list-group-item-success" : "text-muted")"
                style="@(isCompleted ? "cursor:pointer" : "")"
                @onclick="() => GoToStep(step)">
                @if (isCompleted)
                {
                    <span>&#10003; </span>
                }
                @StepNames[step]
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task GoToStep(int step)
    {
        if (step < CurrentStep)
            await OnStepClicked.InvokeAsync(step);
    }
}

@namespace sv_a9dee7a0746c44b0bdb71bd304255b32.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger float-end" @onclick="OnRemove">Remove</button>
        }
        <h6 class="card-subtitle mb-3 text-muted">Position @Index</h6>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input class="form-control" value="@Company" @onchange="e => Update(nameof(Company), e.Value)" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input class="form-control" value="@Title" @onchange="e => Update(nameof(Title), e.Value)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(nameof(StartDate), e.Value)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")"
                       disabled="@IsCurrent"
                       @onchange="e => Update(nameof(EndDate), e.Value)" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check">
                    <input type="checkbox" class="form-check-input" id="@($"current-{Index}")"
                           checked="@IsCurrent" @onchange="e => Update(nameof(IsCurrent), e.Value)" />
                    <label class="form-check-label" for="@($"current-{Index}")">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => Update(nameof(Description), e.Value)"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(string Field, object? Value)> OnFieldChanged { get; set; }

    private async Task Update(string field, object? value)
    {
        await OnFieldChanged.InvokeAsync((field, value));
    }
}

