@namespace sv_a9dee7a0746c44b0bdb71bd304255b32.Components.Pages.Apply

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input class="form-control" value="@FullName" @onchange="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control" value="@Email" @onchange="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control" value="@Phone" @onchange="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input class="form-control" value="@Address" @onchange="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>
</div>

<div class="mt-4 d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public bool IsValidating { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@namespace sv_a9dee7a0746c44b0bdb71bd304255b32.Components.Pages.Apply

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];
    <WorkEntryForm Index="@(index + 1)"
                   Company="@entry.Company"
                   Title="@entry.Title"
                   StartDate="@entry.StartDate"
                   EndDate="@entry.EndDate"
                   IsCurrent="@entry.IsCurrent"
                   Description="@entry.Description"
                   CanRemove="@(Entries.Count > 1)"
                   OnRemove="() => OnRemoveEntry.InvokeAsync(index)"
                   OnFieldChanged="args => OnEntryFieldChanged.InvokeAsync((index, args.Field, args.Value))" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="OnAddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public string? ErrorMessage { get; set; }
    [Parameter] public EventCallback OnAddEntry { get; set; }
