@page "/apply"
@namespace sv_a9dee7a0746c44b0bdb71bd304255b32.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_a9dee7a0746c44b0bdb71bd304255b32.Models
@using sv_a9dee7a0746c44b0bdb71bd304255b32.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              FullNameChanged="v => { fullName = v; StateHasChanged(); }"
                              EmailChanged="v => { email = v; StateHasChanged(); }"
                              PhoneChanged="v => { phone = v; StateHasChanged(); }"
                              AddressChanged="v => { address = v; StateHasChanged(); }"
                              IsValidating="@isValidating" ErrorMessage="@errorMessage"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries" ErrorMessage="@errorMessage"
                             OnAddEntry="AddWorkEntry"
                             OnRemoveEntry="RemoveWorkEntry"
                             OnEntryFieldChanged="UpdateWorkEntryField"
                             OnBack="() => GoToStep(0)" OnNext="HandleWorkNext" />
            break;

        case 2:
            <ReferencesStep References="@references" ErrorMessage="@errorMessage"
                            OnAddReference="AddReference"
                            OnRemoveReference="RemoveReference"
                            OnReferenceFieldChanged="UpdateReferenceField"
                            OnBack="() => GoToStep(1)" OnNext="HandleReferencesNext" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="v => { coverLetter = v; StateHasChanged(); }"
                             OnBack="() => GoToStep(2)" OnNext="() => GoToStep(4)" />
            break;

        case 4:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="@workEntries" References="@references" CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting" IsSubmitted="@isSubmitted" ApplicationId="@applicationId"
                        OnEdit="GoToStep" OnBack="() => GoToStep(3)" OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;
    private string errorMessage = "";
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;

    // Step 1 — Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 — Work History
    private List<WorkEntryModel> workEntries = [new()];

    // Step 3 — References
    private List<ReferenceModel> references = [new(), new()];

    // Step 4 — Cover Letter
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        errorMessage = "";
        currentStep = step;
    }

    // --- Step 1 Handling ---

    private async Task HandlePersonalNext()
    {
        errorMessage = "";

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(email);
            if (!valid)
            {
                errorMessage = "Please enter a valid email address.";
                return;
            }
            GoToStep(1);
        }
        finally
        {
            isValidating = false;
        }
    }

    // --- Step 2 Handling ---

    private void AddWorkEntry() => workEntries.Add(new());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void UpdateWorkEntryField((int Index, string Field, object? Value) args)
    {
        var entry = workEntries[args.Index];
        switch (args.Field)
        {
            case nameof(WorkEntryModel.Company): entry.Company = args.Value?.ToString() ?? ""; break;
            case nameof(WorkEntryModel.Title): entry.Title = args.Value?.ToString() ?? ""; break;
            case nameof(WorkEntryModel.Description): entry.Description = args.Value?.ToString() ?? ""; break;
            case nameof(WorkEntryModel.StartDate):
                entry.StartDate = DateTime.TryParse(args.Value?.ToString(), out var sd) ? sd : null;
                break;
            case nameof(WorkEntryModel.EndDate):
                entry.EndDate = DateTime.TryParse(args.Value?.ToString(), out var ed) ? ed : null;
                break;
            case nameof(WorkEntryModel.IsCurrent):
                entry.IsCurrent = args.Value is true or "True" or "true";
                if (entry.IsCurrent) entry.EndDate = null;
                break;
        }
    }

    private void HandleWorkNext()
    {
        errorMessage = "";
        foreach (var e in workEntries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title) || e.StartDate is null)
            {
                errorMessage = "Each position requires a company name, job title, and start date.";
                return;
            }
        }
        GoToStep(2);
    }

    // --- Step 3 Handling ---

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private void UpdateReferenceField((int Index, string Field, object? Value) args)
    {
        var r = references[args.Index];
        switch (args.Field)
        {
            case nameof(ReferenceModel.Name): r.Name = args.Value?.ToString() ?? ""; break;
            case nameof(ReferenceModel.Relationship): r.Relationship = args.Value?.ToString() ?? ""; break;
            case nameof(ReferenceModel.Email): r.Email = args.Value?.ToString() ?? ""; break;
            case nameof(ReferenceModel.Phone): r.Phone = args.Value?.ToString() ?? ""; break;
        }
    }

    private void HandleReferencesNext()
    {
        errorMessage = "";
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                errorMessage = "Each reference requires at least a name and email.";
                return;
            }
        }
        GoToStep(3);
    }

    // --- Submission ---

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            var app = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
                                  e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );
            applicationId = await ApplicationService.SubmitApplicationAsync(app);
            isSubmitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

/// <summary>Mutable form model for work entries (records are immutable).</summary>
public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

/// <summary>Mutable form model for references.</summary>
public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

