+    {
+        errorMessage = "";
+        foreach (var e in workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title) || e.StartDate is null)
+            {
+                errorMessage = "Each position requires a company name, job title, and start date.";
+                return;
+            }
+        }
+        GoToStep(2);
+    }
+
+    // --- Step 3 Handling ---
+
+    private void AddReference()
+    {
+        if (references.Count < 3)
+            references.Add(new());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (references.Count > 2)
+            references.RemoveAt(index);
+    }
+
+    private void UpdateReferenceField((int Index, string Field, object? Value) args)
+    {
+        var r = references[args.Index];
+        switch (args.Field)
+        {
+            case nameof(ReferenceModel.Name): r.Name = args.Value?.ToString() ?? ""; break;
+            case nameof(ReferenceModel.Relationship): r.Relationship = args.Value?.ToString() ?? ""; break;
+            case nameof(ReferenceModel.Email): r.Email = args.Value?.ToString() ?? ""; break;
+            case nameof(ReferenceModel.Phone): r.Phone = args.Value?.ToString() ?? ""; break;
+        }
+    }
+
+    private void HandleReferencesNext()
+    {
+        errorMessage = "";
+        foreach (var r in references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
+            {
+                errorMessage = "Each reference requires at least a name and email.";
+                return;
+            }
+        }
+        GoToStep(3);
+    }
+
+    // --- Submission ---
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        try
+        {
+            var app = new JobApplication(
+                new PersonalInfo(fullName, email, phone, address),
+                new WorkHistory(workEntries.Select(e =>
+                    new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
+                                  e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
+                references.Select(r =>
+                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                coverLetter
+            );
+            applicationId = await ApplicationService.SubmitApplicationAsync(app);
+            isSubmitted = true;
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+}
+
